  // 3.0: Simple help and the install-statistics question
  'simple.help.g1.title': '连接屏幕',
  'simple.help.g1.s1': '在要使用的电视、平板或电脑上打开播放器：安装 Android 应用，或在浏览器中打开本站的 /player 页面。',
  'simple.help.g1.s2': '手边没有电视？在另一个浏览器标签页中打开播放器试试。',
  'simple.help.g1.s3': '播放器会显示一个 6 位数代码。在这里选择“添加屏幕”并输入它。',
  'simple.help.g1.s4': '给屏幕起一个好认的名字，例如“橱窗”。',
  'simple.help.g2.title': '更改屏幕显示的内容',
  'simple.help.g2.s1': '选择“更改屏幕显示的内容”，或在“你的屏幕”中点按屏幕。',
  'simple.help.g2.s2': '选择“替换”只显示新内容，或选择“添加”保留正在播放的内容。',
  'simple.help.g2.s3': '上传照片或视频，选择之前上传的内容，或与另一块屏幕显示相同内容。',
  'simple.help.g2.s4': '屏幕会在几秒内更新。',
  'simple.help.g3.title': '上传照片和视频',
  'simple.help.g3.s1': '选择“上传照片”，选择任意数量的文件，或直接拖进来。',
  'simple.help.g3.s2': '勾选要显示它们的屏幕，或全部取消勾选以留待以后使用。',
  'simple.help.g3.s3': '每张照片显示 10 秒；视频播放到结束。',
  'simple.help.q1': '哪些设备可以当屏幕用？',
  'simple.help.a1': 'Android 电视、电视盒子和平板、Fire TV、LG 和三星智能电视、树莓派、Windows 和 ChromeOS，或任何带网页浏览器的设备。',
  'simple.help.q2': '我的屏幕没有变化，应该检查什么？',
  'simple.help.a2': '确认屏幕在首页显示“播放中”。如果显示“离线”，请检查设备是否开机并已联网；重新连接后会立即收到您的更改。',
  'simple.help.q3': '网络断了会怎样？',
  'simple.help.a3': '屏幕会在本地保存内容并继续播放。网络恢复后会收到新的更改。',
  'simple.help.q4': '可以上传哪些文件？',
  'simple.help.a4': '照片（JPEG、PNG、GIF、WebP）和视频（MP4 效果最好），以及音频。PDF 可在“高级”视图的内容页面上传。',
  'simple.help.q5': '如何重命名或移除屏幕？',
  'simple.help.a5': '切换到右上角的“高级”，打开“屏幕”，点击该屏幕，然后使用页面顶部的“重命名”或“移除”。',
  'simple.help.q6': '可以在一天中不同时间显示不同内容吗？',
  'simple.help.a6': '可以，这就是“高级”视图中的“排程”。简单视图会一直在屏幕上显示相同内容，直到您更改为止。',
  'simple.help.trial_q': '免费试用是怎样的？',
  'simple.help.trial_a': '您可以免费使用 14 天 Pro 方案，所有功能均可用，无需绑卡。结束后会转为免费方案：不会删除任何内容，超出免费方案上限的屏幕会暂停，直到您选择方案。',
